    ::configureMinimizer() {
        int nSamples = this->_Model->getNSamples();
        int nDims = this->_Model->getNDims();

        bool doReconfigure = false;

        if (!_VnlFitter) {
            doReconfigure = true;
        }

        if (_ModelAdaptedToVnl != 0) {
            if (nSamples != this->_ModelAdaptedToVnl->get_number_of_residuals()) {
                doReconfigure = true;
            }
        }

        if (doReconfigure) {
            if (!this->_Model) {
