			inflater = activity.getLayoutInflater();			

			row = inflater.inflate (R.layout.script_list_item, parent, false);

			listener = new Listener(this, script, row);
			holder = new Holder (row, listener);
			row.setTag (holder);
		}

		holder.fill (scriptStore, script);

		return row;
	}		
