					generators[upgrades[id].GeneratorID].CurrentPerSec += upgrades[id].Effect;
				}
				else if(upgrades[id].Type == 1) // if multiply
				{
					generators[upgrades[id].GeneratorID].CurrentPerSec *= 1 + upgrades[id].Effect;
