		}



		CalculateGeneratorIncome();

		UpdateGeneratorDisplay(id);
		UpdateClickDisplay();
		UpdateCPSDisplay();

		document.getElementById("upg_" + id + "_desc").innerHTML = upgrades[id].Description;
