		break;
	}
	default:
		change_live(true);
		break;
	}
}

void bullet::tick() {
	if (get_live())
	{
		check();
		end_t = clock();
		float sec = (float)(end_t - begin_t) / CLOCKS_PER_SEC;;
		if (sec >= 0.01f)
		{
			begin_t = clock();
			clear();
			fly();
		}
	}
}

void bullet::fly() {
	if (!get_live())
		return;
	switch (dir) {
	case E_DIR_T:
		pos_x--;
		draw();
		break;
	case E_DIR_B:
		pos_x++;
		draw();
		break;
	case E_DIR_R:
		pos_y++;
		draw();
		break;
	case E_DIR_L:
		pos_y--;
		draw();
		break;
	}
}

