binary_tree::iterator& binary_tree::iterator::operator++() {
	if( loc.empty() and next == nullptr )
		val = nullptr;
	while( not loc.empty() or next != nullptr ) {
		if( next != nullptr ) {
			loc.push_back( next );
			next = next->child[0];
		} else {
			next = loc.back();
			loc.pop_back();
			val = next;
			next = next->child[1];
			break;
		}
	}
	return *this;
}

