        if (position < mHintIndex - 1) {
            return TYPE_LOCAL_ALBUM;
        } else if (position == mHintIndex - 1) {
            return TYPE_ADD;
        } else if (position == mHintIndex) {
            return TYPE_HINT;
        } else {
            return TYPE_RANDOM_ALBUM;
        }
